/**
 * The clear-column schema lint (C01 CP-13 "no clear column outside the declared set"; C01 §2.3, §3.12; RFC-005 §5.4,
 * RK-8 "schema lint at build").
 *
 * The declared set of a kind: the C01 §2.3 columns of its generated tables and each projection's `clearColumns`.
 * A sealed column holds C13 ciphertext, so it is BYTES: `audit` and `payload` of the log, `payload` of the outbox,
 * and every projection column outside `clearColumns`. Any other column is a clear column outside the declared set.
 * The lint reads the statements (generated by `kindMigration`, or given), so a hand-edited schema is checked too.
 */
import type { OwnerDeclaration } from '@share/owner-runtime';
import { tableNames } from '@share/owner-runtime';

/** Why a column is refused. */
export type ClearColumnReason =
  | 'UNDECLARED_COLUMN'   // a clear column not in C01 §2.3 and not in the projection's clearColumns
  | 'SEALED_NOT_BYTES'    // a column C01 §2.3 seals (C13 ciphertext) whose type cannot hold ciphertext
  | 'UNDECLARED_TABLE';   // a table the declaration does not produce: none of its columns is declared

export interface ClearColumnViolation { table: string; column: string; type: string; reason: ClearColumnReason }

export class ClearColumnError extends Error {
  readonly code = 'CLEAR_COLUMN_UNDECLARED' as const;
  readonly violations: ClearColumnViolation[];
  constructor(kind: string, violations: ClearColumnViolation[]) {
    super(`CLEAR_COLUMN_UNDECLARED: kind ${kind}: ${violations.map((v) => `${v.table}.${v.column} ${v.type} (${v.reason})`).join('; ')}`);
    this.name = 'ClearColumnError';
    this.violations = violations;
  }
}

/** C01 §2.3: the clear and sealed columns of each generated table. */
const LOG_CLEAR = ['slot', 'partition', 'seq', 'generation', 'epoch', 'kind', 'schema_v', 'ts', 'identity', 'emits', 'retention', 'key_id', 'chain'];
const LOG_SEALED = ['audit', 'payload'];
const HEAD_CLEAR = ['home_key', 'partition', 'slot', 'generation', 'adopted', 'seq', 'ts', 'epoch', 'streams', 'chain', 'batch_id'];
const OUTBOX_CLEAR = ['slot', 'partition', 'stream', 'stream_seq', 'n', 'topic', 'msg_key', 'headers', 'ts', 'generation', 'epoch'];
const OUTBOX_SEALED = ['payload'];
const STREAM_INDEX_CLEAR = ['partition', 'stream', 'stream_seq', 'seq'];

/** A table's declared set: `clear` columns, `sealed` columns (BYTES), and whether other BYTES columns are sealed. */
interface Declared { clear: Set<string>; sealed: Set<string>; otherBytesSealed: boolean }

function declaredTables(d: OwnerDeclaration): Map<string, Declared> {
  const t = tableNames(d.kind);
  const m = new Map<string, Declared>();
  const fixed = (clear: string[], sealed: string[] = []): Declared => ({ clear: new Set(clear), sealed: new Set(sealed), otherBytesSealed: false });
  m.set(t.log, fixed(LOG_CLEAR, LOG_SEALED));
  m.set(t.head, fixed(HEAD_CLEAR));
  if (d.selfOutboxed) m.set(t.streamIndex, fixed(STREAM_INDEX_CLEAR));
  else m.set(t.outbox, fixed(OUTBOX_CLEAR, OUTBOX_SEALED));
  for (const p of d.projections) {
    m.set(t.projection(p.name), { clear: new Set(p.clearColumns.map((c) => c.toLowerCase())), sealed: new Set(), otherBytesSealed: true });
  }
  return m;
}

const BYTES_TYPES = new Set(['BYTES', 'BYTEA', 'BLOB']);
/** Table elements that are not column definitions. */
const CONSTRAINT_WORDS = new Set(['PRIMARY', 'UNIQUE', 'INDEX', 'INVERTED', 'CONSTRAINT', 'FAMILY', 'CHECK', 'FOREIGN', 'EXCLUDE']);

/** Split `s` at commas that are not inside parentheses or quotes. */
function splitTopLevel(s: string): string[] {
  const out: string[] = [];
  let depth = 0;
  let quote = '';
  let cur = '';
  for (const ch of s) {
    if (quote) { if (ch === quote) quote = ''; }
    else if (ch === '\'' || ch === '"') quote = ch;
    else if (ch === '(') depth++;
    else if (ch === ')') depth--;
    else if (ch === ',' && depth === 0) { out.push(cur); cur = ''; continue; }
    cur += ch;
  }
  out.push(cur);
  return out.map((x) => x.trim()).filter((x) => x.length > 0);
}

/** Column name and base type of one column definition, or null for a constraint or index. */
function columnOf(def: string): { column: string; type: string } | null {
  const m = /^("[^"]+"|\S+)\s+([A-Za-z_][A-Za-z0-9_]*)/.exec(def);
  if (!m || m[1] === undefined || m[2] === undefined) return null;
  if (CONSTRAINT_WORDS.has(m[1].toUpperCase())) return null;
  return { column: m[1].replace(/"/g, '').toLowerCase(), type: m[2].toUpperCase() };
}

/** Every column the statements define: CREATE TABLE bodies and ALTER TABLE … ADD COLUMN. */
function definedColumns(statements: string[]): Array<{ table: string; column: string; type: string }> {
  const out: Array<{ table: string; column: string; type: string }> = [];
  for (const s of statements) {
    const create = /^\s*CREATE\s+TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?("[^"]+"|[\w.]+)\s*\(/i.exec(s);
    if (create && create[1] !== undefined) {
      const table = create[1].replace(/"/g, '').toLowerCase();
      let depth = 1;
      let i = create[0].length;
      for (; i < s.length && depth > 0; i++) {
        if (s[i] === '(') depth++;
        else if (s[i] === ')') depth--;
      }
      for (const def of splitTopLevel(s.slice(create[0].length, i - 1))) {
        const c = columnOf(def);
        if (c) out.push({ table, ...c });
      }
      continue;
    }
    const alter = /^\s*ALTER\s+TABLE\s+(?:IF\s+EXISTS\s+)?("[^"]+"|[\w.]+)\s+(.*)$/is.exec(s);
    if (alter && alter[1] !== undefined && alter[2] !== undefined) {
      const table = alter[1].replace(/"/g, '').toLowerCase();
      for (const action of splitTopLevel(alter[2])) {
        const add = /^ADD\s+(?:COLUMN\s+)?(?:IF\s+NOT\s+EXISTS\s+)?(.*)$/is.exec(action);
        if (!add || add[1] === undefined) continue;
        const c = columnOf(add[1]);
        if (c) out.push({ table, ...c });
      }
    }
  }
  return out;
}

/** The clear columns outside the declared set of `d`, in statement order. Empty when the schema conforms. */
export function lintClearColumns(d: OwnerDeclaration, statements: string[]): ClearColumnViolation[] {
  const declared = declaredTables(d);
  const out: ClearColumnViolation[] = [];
  for (const { table, column, type } of definedColumns(statements)) {
    const t = declared.get(table);
    const bytes = BYTES_TYPES.has(type);
    if (!t) out.push({ table, column, type, reason: 'UNDECLARED_TABLE' });
    else if (t.clear.has(column)) continue;
    else if (t.sealed.has(column)) { if (!bytes) out.push({ table, column, type, reason: 'SEALED_NOT_BYTES' }); }
    else if (!(t.otherBytesSealed && bytes)) out.push({ table, column, type, reason: 'UNDECLARED_COLUMN' });
  }
  return out;
}

/** Throw `ClearColumnError` (`CLEAR_COLUMN_UNDECLARED`) when the schema has a clear column outside the declared set. */
export function assertClearColumns(d: OwnerDeclaration, statements: string[]): void {
  const v = lintClearColumns(d, statements);
  if (v.length > 0) throw new ClearColumnError(d.kind, v);
}
